class BankAccount {const BankAccount({required this.id,required this.name,required this.bankName,required this.openingBalance});final int? id;final String name;final String bankName;final double openingBalance;Map<String,Object?>toMap()=>{'id':id,'name':name,'bank_name':bankName,'opening_balance':openingBalance};factory BankAccount.fromMap(Map<String,Object?>r)=>BankAccount(id:r['id'] as int,name:r['name'] as String,bankName:r['bank_name'] as String,openingBalance:(r['opening_balance'] as num).toDouble());}
class BankTransaction {const BankTransaction({required this.id,required this.accountId,required this.date,required this.description,required this.amount,required this.direction,required this.reference,this.reconciled=false});final int? id;final int accountId;final DateTime date;final String description;final double amount;final String direction;final String reference;final bool reconciled;Map<String,Object?>toMap()=>{'id':id,'account_id':accountId,'date':date.toIso8601String(),'description':description,'amount':amount,'direction':direction,'reference':reference,'reconciled':reconciled?1:0};factory BankTransaction.fromMap(Map<String,Object?>r)=>BankTransaction(id:r['id'] as int,accountId:r['account_id'] as int,date:DateTime.parse(r['date'] as String),description:r['description'] as String,amount:(r['amount'] as num).toDouble(),direction:r['direction'] as String,reference:(r['reference']??'') as String,reconciled:(r['reconciled'] as int)==1);}
class StockCost {const StockCost({required this.id,required this.date,required this.item,required this.quantity,required this.unitCost,required this.kind,this.note=''});final int? id;final DateTime date;final String item;final double quantity;final double unitCost;final String kind;final String note;double get totalCost=>quantity*unitCost;Map<String,Object?>toMap()=>{'id':id,'date':date.toIso8601String(),'item':item,'quantity':quantity,'unit_cost':unitCost,'kind':kind,'note':note};factory StockCost.fromMap(Map<String,Object?>r)=>StockCost(id:r['id'] as int,date:DateTime.parse(r['date'] as String),item:r['item'] as String,quantity:(r['quantity'] as num).toDouble(),unitCost:(r['unit_cost'] as num).toDouble(),kind:r['kind'] as String,note:(r['note']??'') as String);}
